import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Epic: Core Inference & Chat","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/core-inference-chat.md","filePath":"sovereign-edge/epics/core-inference-chat.md"}'),i={name:"sovereign-edge/epics/core-inference-chat.md"};function o(l,e,s,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="epic-core-inference-chat" tabindex="-1">Epic: Core Inference &amp; Chat <a class="header-anchor" href="#epic-core-inference-chat" aria-label="Permalink to &quot;Epic: Core Inference &amp; Chat&quot;">​</a></h1><blockquote><p><code>llama.rn</code>/GGUF engine, model manager, and a fully offline chat and writing assistant — the part of the app with no network code path at all.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>⏳ In Progress</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The foundation the entire privacy claim rests on. Everything in this epic must work with the device in airplane mode. This is scenario 1 from the original brainstorm: open the app, brainstorm something, fix grammar, draft/rewrite an email — all fully local.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-1-1-—-llama-rn-integration-and-inference-engine-wrapper" tabindex="-1">📋 1.1 — <code>llama.rn</code> integration and inference engine wrapper <a class="header-anchor" href="#📋-1-1-—-llama-rn-integration-and-inference-engine-wrapper" aria-label="Permalink to &quot;📋 1.1 — `llama.rn` integration and inference engine wrapper&quot;">​</a></h4><p><strong>Goal:</strong> Get a GGUF model running on-device via <code>llama.rn</code>, wrapped in a clean internal API the chat UI and connector framework both call.</p><p><strong>Deliverables:</strong></p><ul><li><code>llama.rn</code> integrated for both iOS and Android.</li><li>An internal inference wrapper (load model, stream tokens, unload model) independent of any specific model file.</li><li>Basic perf validation on a real low/mid-range device, not just a simulator/emulator.</li></ul><p><strong>Dependencies:</strong> Task 0.1 (repo scaffold), Task 0.4 (model asset pipeline).</p><p><strong>Review checklist:</strong></p><ul><li>Chat streams tokens from a locally-downloaded GGUF model with the device&#39;s network interfaces disabled.</li></ul><hr><h4 id="✅-1-2-—-model-manager" tabindex="-1">✅ 1.2 — Model manager <a class="header-anchor" href="#✅-1-2-—-model-manager" aria-label="Permalink to &quot;✅ 1.2 — Model manager&quot;">​</a></h4><p><strong>Goal:</strong> Let a user pick, download, and manage which small model is installed.</p><p><strong>Deliverables:</strong></p><ul><li>Curated model catalog (small GGUF models — Gemma/Qwen/Phi-class; final list is an open question, see research 0001).</li><li>RAM-aware guidance/warnings per model, given the phone&#39;s available memory.</li><li>Delete/switch-model flow.</li></ul><p><strong>Dependencies:</strong> Task 1.1, Task 0.4.</p><p><strong>Review checklist:</strong></p><ul><li>✅ A user can download one model, chat, delete it, and download a different one without restarting the app. Verified end to end on an Android emulator: Qwen2.5 0.5B downloaded and verified (57s), loaded in 1.3s, replied &quot;Hello! How may I assist you?&quot;, was deleted; then Llama 3.2 1B downloaded, loaded in 2.8s, replied, and was deleted — all in one app session.</li><li>✅ The Llama entry carries no MD5, so it was verified purely against the publisher&#39;s SHA-256: 807 MB in 1.0s (~790 MB/s) via the native module from task <a href="./infrastructure.html#-05--native-sha-256-hashing">0.5</a>. The same check would have taken roughly ten minutes of JavaScript hashing before it.</li></ul><hr><h4 id="📋-1-3-—-offline-chat-ui" tabindex="-1">📋 1.3 — Offline chat UI <a class="header-anchor" href="#📋-1-3-—-offline-chat-ui" aria-label="Permalink to &quot;📋 1.3 — Offline chat UI&quot;">​</a></h4><p><strong>Goal:</strong> The core conversational interface.</p><p><strong>Deliverables:</strong></p><ul><li>Conversation view with streaming token rendering.</li><li>Local-only chat history (no export/sync in this task — that&#39;s a future, explicit opt-in decision per research 0001-equivalent follow-up).</li><li>Persistent visible indicator that the current conversation is fully offline (per CONCEPT.md&#39;s &quot;always show which trust tier is active&quot;).</li></ul><p><strong>Dependencies:</strong> Task 1.1.</p><p><strong>Review checklist:</strong></p><ul><li>Chat is fully usable with the device offline.</li></ul><hr><h4 id="📋-1-4-—-writing-assist-modes" tabindex="-1">📋 1.4 — Writing-assist modes <a class="header-anchor" href="#📋-1-4-—-writing-assist-modes" aria-label="Permalink to &quot;📋 1.4 — Writing-assist modes&quot;">​</a></h4><p><strong>Goal:</strong> The concrete scenario-1 use case — brainstorm, grammar-fix, rewrite/draft an email.</p><p><strong>Deliverables:</strong></p><ul><li>A small set of prompt-engineered modes/personas (brainstorm, fix grammar, rewrite tone, draft from bullet points) surfaced as quick actions in chat.</li><li>No connector involved — these are pure local-model tasks.</li></ul><p><strong>Dependencies:</strong> Task 1.3.</p><p><strong>Review checklist:</strong></p><ul><li>Each mode produces a materially different, appropriate transformation of the same input text.</li></ul><hr><h4 id="📋-1-5-—-zero-network-enforcement-and-audit" tabindex="-1">📋 1.5 — Zero-network enforcement and audit <a class="header-anchor" href="#📋-1-5-—-zero-network-enforcement-and-audit" aria-label="Permalink to &quot;📋 1.5 — Zero-network enforcement and audit&quot;">​</a></h4><p><strong>Goal:</strong> Make the &quot;fully offline&quot; claim structurally true, not just true by current code review.</p><p><strong>Deliverables:</strong></p><ul><li>A build-time or lint-time check (or platform network-permission configuration) that fails if any code path reachable from the chat/ inference module can make a network call.</li><li>Document the enforcement mechanism so it&#39;s auditable by a third party, not just asserted in prose.</li></ul><p><strong>Dependencies:</strong> Task 1.1.</p><p><strong>Review checklist:</strong></p><ul><li>Attempting to add a network call inside the chat/inference module fails CI or the build, not just code review.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul>',48)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
